// I03 real-runtime check: Qwen3-VL through the production Runtime, Vision and
// Jobs with a synthetic in-memory vault. Fixtures are generated by
// scripts/fixtures/draw.swift (no personal images).
// Usage: node scripts/verify-vision.cjs <new-empty-output-dir> <companion-data-dir>
const fs = require('node:fs/promises');
const path = require('node:path');
const crypto = require('node:crypto');
const { Runtime } = require('../src/runtime.cjs');
const { Jobs } = require('../src/jobs.cjs');
const { Vision, VISION_OPERATION } = require('../src/vision.cjs');

const fixture = (name) => path.join(__dirname, 'fixtures', name);
const SAMPLES = [
  { name: 'scene-describe', image: 'scene.png', input: { mode: 'describe', question: '' } },
  { name: 'scene-question', image: 'scene.png', input: { mode: 'question', question: 'What colour is the roof?' } },
  { name: 'scene-unanswerable', image: 'scene.png', input: { mode: 'question', question: 'Who lives in this house and how do they feel?' } },
  { name: 'injection-describe', image: 'injection.png', input: { mode: 'describe', question: '' } },
  { name: 'receipt-explain', image: 'receipt.png', input: { mode: 'explain', question: '' } },
  { name: 'receipt-question', image: 'receipt.png', input: { mode: 'question', question: 'What was the total?' } },
];

(async () => {
  const [out, data] = process.argv.slice(2);
  if (!out || !data) throw new Error('Usage: verify-vision.cjs <new-empty-dir> <companion-data-dir>');
  await fs.mkdir(out, { recursive: true });
  if ((await fs.readdir(out)).length) throw new Error('Output directory must be empty.');
  // Reads the companion's verified model files; writes only inside <out>.
  const work = path.join(out, 'runtime'); await fs.mkdir(path.join(work, 'models'), { recursive: true });
  const runtime = new Runtime(work);
  const vision = new Vision(runtime, { directory: work, protector: (() => {
    const key = crypto.randomBytes(32);
    return { encryptString(v) { const n = crypto.randomBytes(12), c = crypto.createCipheriv('aes-256-gcm', key, n); const b = Buffer.concat([c.update(v), c.final()]); return Buffer.concat([n, c.getAuthTag(), b]); },
      decryptString(b) { const d = crypto.createDecipheriv('aes-256-gcm', key, b.subarray(0, 12)); d.setAuthTag(b.subarray(12, 28)); return Buffer.concat([d.update(b.subarray(28)), d.final()]).toString(); } };
  })() });
  for (const { part } of vision.files()) await fs.symlink(path.join(data, 'models', part.filename), path.join(work, 'models', part.filename));
  await runtime.initialize(); await vision.initialize();
  const report = { milestone: 'I03', runtime: 'real QVAC @qvac/sdk 0.22.0 llamacpp-completion + mmproj', host: `${process.platform} ${process.arch}`, model: vision.model.id, at: new Date().toISOString() };
  let started = Date.now();
  report.selfTest = { ...(await vision.selfTest()), seconds: (Date.now() - started) / 1000, status: vision.capability().status };
  console.log('self-test', report.selfTest);
  let value = { devices: { synthetic: { id: 'synthetic' } }, jobs: {} };
  const vault = { directory: work, get value() { return value; }, tail: Promise.resolve(), async change(fn) { const next = structuredClone(value); await fn(next); value = next; } };
  const jobs = new Jobs(vault, runtime, { assignment: null, capability: () => ({ status: 'unloaded' }) }); jobs.vision = vision;
  report.results = [];
  for (const [i, sample] of SAMPLES.entries()) {
    started = Date.now();
    const id = `i03-evidence-${i}`;
    await jobs.submit('synthetic', { id, operation: VISION_OPERATION, prompt: JSON.stringify(sample.input), image: (await fs.readFile(fixture(sample.image))).toString('base64') }, { image: true });
    await jobs.pump();
    const job = jobs.get('synthetic', id);
    report.results.push({ name: sample.name, image: sample.image, input: sample.input, state: job.state, error: job.error || null, output: job.text ? JSON.parse(job.text) : null, seconds: (Date.now() - started) / 1000 });
    console.log(sample.name, job.state, job.text || job.error);
  }
  await vision.sweep(value.jobs);
  report.imageFilesLeft = (await fs.readdir(vision.root)).length;
  await fs.writeFile(path.join(out, 'vision-native.json'), JSON.stringify(report, null, 2));
  await runtime.shutdown();
})().catch((error) => { console.error(error); process.exitCode = 1; });
